#include <jxl/decode.h>
#include <cstdio>
#include <vector>
#include <string>
#include <fstream>
#include <iostream>
int main(int argc,char**argv){if(argc!=4)return 2;FILE*f=fopen(argv[1],"rb");if(!f)return 3;std::string out=argv[2];bool cancel=std::string(argv[3])=="cancel";auto*d=JxlDecoderCreate(nullptr);JxlDecoderSubscribeEvents(d,JXL_DEC_BASIC_INFO|JXL_DEC_FRAME|JXL_DEC_FRAME_PROGRESSION|JXL_DEC_FULL_IMAGE);JxlDecoderSetProgressiveDetail(d,kDC);JxlPixelFormat fmt={3,JXL_TYPE_UINT8,JXL_NATIVE_ENDIAN,0};std::vector<unsigned char>pending,pixels;size_t provided=0,consumed=0,firstProvided=0,firstConsumed=0,firstRatio=0;unsigned width=0,height=0;bool inputSet=false,full=false,gotPreview=false;int rc=0;auto release=[&](){if(inputSet){size_t remaining=JxlDecoderReleaseInput(d);consumed+=pending.size()-remaining;pending.erase(pending.begin(),pending.end()-remaining);inputSet=false;}};auto dump=[&](const char*name){std::ofstream o(out+"/"+name,std::ios::binary);o.write((char*)pixels.data(),pixels.size());};for(;;){if(!inputSet){unsigned char chunk[64];size_t n=fread(chunk,1,64,f);provided+=n;pending.insert(pending.end(),chunk,chunk+n);JxlDecoderSetInput(d,pending.data(),pending.size());inputSet=true;if(n<64)JxlDecoderCloseInput(d);}auto status=JxlDecoderProcessInput(d);if(status==JXL_DEC_NEED_MORE_INPUT){release();if(feof(f)){rc=4;break;}}else if(status==JXL_DEC_BASIC_INFO){JxlBasicInfo info;if(JxlDecoderGetBasicInfo(d,&info)!=JXL_DEC_SUCCESS){rc=5;break;}width=info.xsize;height=info.ysize;pixels.resize((size_t)width*height*3);}else if(status==JXL_DEC_NEED_IMAGE_OUT_BUFFER){if(JxlDecoderSetImageOutBuffer(d,&fmt,pixels.data(),pixels.size())!=JXL_DEC_SUCCESS){rc=6;break;}}else if(status==JXL_DEC_FRAME_PROGRESSION){if(!gotPreview){firstRatio=JxlDecoderGetIntendedDownsamplingRatio(d);if(JxlDecoderFlushImage(d)!=JXL_DEC_SUCCESS){rc=7;break;}dump("preview.rgb");size_t remaining=JxlDecoderReleaseInput(d);firstConsumed=consumed+pending.size()-remaining;firstProvided=provided;consumed=firstConsumed;pending.erase(pending.begin(),pending.end()-remaining);inputSet=false;gotPreview=true;if(cancel)break;JxlDecoderSetInput(d,pending.data(),pending.size());inputSet=true;}}else if(status==JXL_DEC_FULL_IMAGE){dump("full.rgb");full=true;}else if(status==JXL_DEC_SUCCESS){release();break;}else if(status==JXL_DEC_ERROR){rc=8;break;}}JxlDecoderDestroy(d);fclose(f);std::cout<<"{\"width\":"<<width<<",\"height\":"<<height<<",\"first_ratio\":"<<firstRatio<<",\"first_consumed\":"<<firstConsumed<<",\"first_provided\":"<<firstProvided<<",\"final_consumed\":"<<consumed<<",\"final_provided\":"<<provided<<",\"preview\":"<<(gotPreview?"true":"false")<<",\"full\":"<<(full?"true":"false")<<",\"cancelled\":"<<(cancel?"true":"false")<<",\"decoder_destroyed\":true,\"exit\":"<<rc<<"}\n";return rc;}
